function Icon({ name, size = 18 }: { name: string; size?: number }) {
  return <svg className="icon" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{icons[name]}</svg>;
}

function GoogleMark() {
  return <svg className="google-mark" viewBox="0 0 24 24" aria-hidden="true"><path fill="#4285F4" d="M21.6 12.23c0-.71-.06-1.4-.18-2.07H12v3.92h5.38a4.6 4.6 0 0 1-2 3.02v2.55h3.24c1.9-1.75 2.98-4.33 2.98-7.42Z"/><path fill="#34A853" d="M12 22c2.7 0 4.98-.9 6.63-2.35l-3.24-2.55c-.9.6-2.05.96-3.39.96-2.61 0-4.82-1.76-5.61-4.13H3.04v2.63A10 10 0 0 0 12 22Z"/><path fill="#FBBC05" d="M6.39 13.93A6 6 0 0 1 6.08 12c0-.67.11-1.32.31-1.93V7.44H3.04A10 10 0 0 0 2 12c0 1.64.39 3.19 1.04 4.56l3.35-2.63Z"/><path fill="#EA4335" d="M12 5.94c1.47 0 2.79.5 3.82 1.5l2.88-2.88A9.65 9.65 0 0 0 12 2a10 10 0 0 0-8.96 5.44l3.35 2.63C7.18 7.7 9.39 5.94 12 5.94Z"/></svg>;
}

function Logo({ light = false }: { light?: boolean }) {
  return <div className={`logo ${light ? "logo-light" : ""}`}><span className="logo-mark"><span /></span><strong>Triply</strong></div>;
}

function Button({ children, variant = "primary", icon, onClick, className = "" }: { children: ReactNode; variant?: "primary" | "secondary" | "ghost" | "danger" | "dark"; icon?: string; onClick?: () => void; className?: string }) {
  return <button className={`btn btn-${variant} ${className}`} onClick={onClick}>{icon && <Icon name={icon} />}{children}</button>;
}

function Badge({ children, tone = "neutral" }: { children: ReactNode; tone?: "neutral" | "success" | "warning" | "teal" | "yellow" | "danger" }) {
  return <span className={`badge badge-${tone}`}>{children}</span>;
}

function Avatar({ label, color = "green" }: { label: string; color?: string }) {
  return <span className={`avatar avatar-${color}`}>{label}</span>;
}

const navItems = [
  ["home", "Trang chủ", "trips"],
  ["compass", "Khám phá", "discover"],
  ["map", "Chuyến đi của tôi", "trips"],
  ["bookmark", "Đặt chỗ", "bookings"],
  ["wallet", "Quỹ nhóm", "funds"],
  ["settings", "Cài đặt", "settings"],
] as const;

function Shell({ screen, setScreen, children, action }: { screen: Screen; setScreen: (s: Screen) => void; children: ReactNode; action?: ReactNode }) {
  return <div className="app-shell">
    <aside className="sidebar">
      <Logo />
      <nav>{navItems.map(([icon, label, target]) => <button key={label} onClick={() => setScreen(target)} className={(screen === target || (screen === "settle" && target === "funds") || (screen === "detail" && target === "trips") || (screen === "itinerary" && target === "trips") || (screen === "create" && target === "trips")) ? "active" : ""}><Icon name={icon}/><span>{label}</span></button>)}</nav>
      <div className="sidebar-bottom"><button className="profile" onClick={() => setScreen("settings")}><Avatar label="AL" color="yellow"/><span><strong>An Lê</strong><small>an.le@gmail.com</small></span><Icon name="chevron" size={15}/></button></div>
    </aside>
    <main className="app-main">
      <header className="mobile-bar"><Logo/><Button variant="ghost" icon="menu">Menu</Button></header>
      {action && <div className="floating-action">{action}</div>}
      {children}
    </main>
  </div>;
}

